import{_ as i,C as d,o as n,c as s,j as r,a,E as o,a2 as l}from"./chunks/framework.BxGh02fV.js";const y=JSON.parse('{"title":"Evolutions register","description":"","frontmatter":{"title":"Evolutions register"},"headers":[],"relativePath":"en/agent/evolutions.md","filePath":"en/agent/evolutions.md"}'),c={name:"en/agent/evolutions.md"};function h(u,e,f,g,v,m){const t=d("Ask");return n(),s("div",null,[e[0]||(e[0]=r("h1",{id:"evolutions-register",tabindex:"-1"},[a("Evolutions register "),r("a",{class:"header-anchor",href:"#evolutions-register","aria-label":'Permalink to "Evolutions register"'},"​")],-1)),e[1]||(e[1]=r("p",null,"The register keeps everything worth remembering that is not handled right away: a defect spotted in passing, an idea, an improvement, a discovery. You come here to have the agent note these things, sort them, then decide with you what becomes of them.",-1)),e[2]||(e[2]=r("h2",{id:"what-you-ask-the-agent",tabindex:"-1"},[a("What you ask the agent "),r("a",{class:"header-anchor",href:"#what-you-ask-the-agent","aria-label":'Permalink to "What you ask the agent"'},"​")],-1)),o(t,{say:"Log an anomaly: the export crashes when the name contains an apostrophe.",verb:"effortless_evolution_add",family:"evolutions",args:'{"type":"Anomalie","title":"The export crashes when the name contains an apostrophe"}'}),o(t,{say:"Add an improvement idea: a dark mode for the Release screen.",verb:"effortless_evolution_add",family:"evolutions",args:'{"type":"Amélioration","title":"Dark mode for the Release screen"}'}),o(t,{say:"Set evolution EVO-041 to criticality 1 and priority 2.",verb:"effortless_evolution_edit",family:"evolutions",args:'{"evo_id":"EVO-041","criticality":"1","priority":"2"}'}),o(t,{say:"What should I pick up next? Show me the queue.",verb:"effortless_evolution_queue",family:"evolutions"}),o(t,{say:"Turn evolution EVO-041 into an epic in the Data zone.",verb:"effortless_evolution_graduate",family:"evolutions",args:'{"evo_id":"EVO-041","zone":"Data"}'}),o(t,{say:"Evolution EVO-041 is handled: resolve it, it was fixed by the export fix.",verb:"effortless_evolution_resolve",family:"evolutions",args:'{"evo_id":"EVO-041","note":"Fixed by the export fix"}'}),o(t,{say:"Retire EVO-041, we will not do it: the customer changed their mind.",verb:"effortless_evolution_retire",family:"evolutions",args:'{"evo_id":"EVO-041","reason":"The customer changed their mind"}'}),o(t,{say:"EVO-041 can only start after epic 12 is closed.",verb:"effortless_evolution_depends_on",family:"evolutions",args:'{"evo_id":"EVO-041","target":"12"}'}),e[3]||(e[3]=l('<h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><h3 id="log-an-evolution" tabindex="-1">Log an evolution <a class="header-anchor" href="#log-an-evolution" aria-label="Permalink to &quot;Log an evolution&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/evolutions.html#evolution-add"><code>effortless_evolution_add</code></a> records the entry. The <code>type</code> is one of five markers: <code>Découverte</code> (discovery), <code>Fonctionnalité</code> (feature), <code>Amélioration</code> (improvement), <code>Anomalie</code> (anomaly) or <code>Test</code>. The agent also passes the <code>title</code>, and if needed:</p><ul><li><code>detail</code>: the full text;</li><li><code>reporter</code>: who reports the entry;</li><li><code>criticality</code> and <code>priority</code>: integers from 1 to 3, 1 being the most urgent. Without them, the entry stays <strong>unranked</strong>;</li><li><code>status</code>: <code>Planifié</code> (planned) by default. For a given type (other than <code>Anomalie</code>), if the quota of active entries is reached, the entry is set to <code>En Attente</code> (on hold);</li><li><code>born_marker</code>: a stable text fragment that names the defect in the git-tracked code. During a piece of work, the engine then checks whether the defect existed before the story. If it was born from that work, the entry is refused: you fix it within the work.</li></ul><p>The reply carries an <code>implication</code>: suggested verbs. The agent never triggers them on its own.</p><h3 id="read-and-sort" tabindex="-1">Read and sort <a class="header-anchor" href="#read-and-sort" aria-label="Permalink to &quot;Read and sort&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/evolutions.html#evolution-list"><code>effortless_evolution_list</code></a>: read-only. Optional filters: <code>status</code> (<code>Planifié</code>, <code>En cours</code>, <code>En Attente</code>, <code>Résolu</code>, <code>Retiré</code>), <code>query</code> (case-insensitive search in the identifier, title and detail) and <code>form</code> (<code>full</code> or <code>compact</code>).</li><li><a href="/Effortless/en/reference/mcp/evolutions.html#evolution-queue"><code>effortless_evolution_queue</code></a>: read-only. The queue of active entries, already sorted by the engine: first those whose dependency is no longer pending, then criticality, priority, age, identifier. It answers &quot;what do I pick up next&quot;. <code>limit</code> bounds the window (25 by default, 200 at most); the total is returned alongside.</li></ol><h3 id="qualify" tabindex="-1">Qualify <a class="header-anchor" href="#qualify" aria-label="Permalink to &quot;Qualify&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/evolutions.html#evolution-edit"><code>effortless_evolution_edit</code></a>: corrects <code>criticality</code>, <code>priority</code> and <code>detail</code>. The previous detail text is kept, never overwritten. Also works on an entry that is already resolved or retired. Touches neither the title, the status nor the type.</li><li><a href="/Effortless/en/reference/mcp/evolutions.html#evolution-requalify"><code>effortless_evolution_requalify</code></a>: switches an entry from <code>Anomalie</code> to <code>Amélioration</code>, or the reverse, and nothing else. The identifier does not change.</li><li><a href="/Effortless/en/reference/mcp/evolutions.html#evolution-set-ready"><code>effortless_evolution_set_ready</code></a>: sets or clears the &quot;ready to graduate&quot; flag (<code>ready</code>).</li></ol><h3 id="order-by-dependency" tabindex="-1">Order by dependency <a class="header-anchor" href="#order-by-dependency" aria-label="Permalink to &quot;Order by dependency&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/evolutions.html#evolution-depends-on"><code>effortless_evolution_depends_on</code></a> declares that an evolution (<code>evo_id</code>) waits for another evolution or an epic (<code>target</code>) to be closed. It falls behind in the queue until the target is closed, without being retired or dropped from the count. Without <code>target</code>, the dependency is lifted.</p><h3 id="promote-into-an-epic" tabindex="-1">Promote into an epic <a class="header-anchor" href="#promote-into-an-epic" aria-label="Permalink to &quot;Promote into an epic&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/evolutions.html#evolution-graduate"><code>effortless_evolution_graduate</code></a> attaches the evolution to an existing epic (<code>epic_id</code>) or creates one and activates it from a <code>zone</code> (with optional <code>title</code> and <code>description</code>). It creates no story: that is the next step (<a href="/Effortless/en/agent/piloter.html">Run the work</a>).</p><h3 id="close-without-going-through-an-epic" tabindex="-1">Close without going through an epic <a class="header-anchor" href="#close-without-going-through-an-epic" aria-label="Permalink to &quot;Close without going through an epic&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/evolutions.html#evolution-resolve"><code>effortless_evolution_resolve</code></a>: resolves the evolution. The <code>note</code>, which says what settled it, is mandatory.</li><li><a href="/Effortless/en/reference/mcp/evolutions.html#evolution-retire"><code>effortless_evolution_retire</code></a>: explicitly sets it aside (status <code>Retiré</code>). The <code>reason</code> is mandatory. Works even on an evolution already promoted into an epic; never sets <code>Résolu</code>.</li></ol><h3 id="upgrade-an-old-register" tabindex="-1">Upgrade an old register <a class="header-anchor" href="#upgrade-an-old-register" aria-label="Permalink to &quot;Upgrade an old register&quot;">​</a></h3><p>Two verbs are used once, on a register inherited from an earlier version. They can be replayed without side effects.</p><ol><li><a href="/Effortless/en/reference/mcp/evolutions.html#evolution-migrate-markers"><code>effortless_evolution_migrate_markers</code></a>: converts the old <code>type</code> field (finding, besoin, amélioration, refonte, chantier) to one of the five markers. No identifier changes.</li><li><a href="/Effortless/en/reference/mcp/evolutions.html#evolution-migrate-levels"><code>effortless_evolution_migrate_levels</code></a>: converts hand-written levels to integers. Its reply names every value it could not convert.</li></ol><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li>The register in the <a href="/Effortless/en/guide/backlog.html">Backlog</a> screen, <strong>Registre</strong> root, <strong>Registre des évolutions</strong> tab: identifier, <strong>Type</strong>, title, <strong>State</strong>, <strong>Criticality</strong>, <strong>Priority</strong>, with search and the <strong>Marker</strong> and <strong>Hide Resolved/Retired</strong> filters.</li><li>The same register rendered as Markdown in <code>blueprints/4-Evolutions.md</code>.</li><li>A promoted evolution becomes an epic visible in the Backlog, under <strong>Project</strong>.</li><li>When an epic is closed, the evolutions it leaves <strong>In progress</strong> are named: they do not resolve themselves.</li></ul><h2 id="when-the-agent-is-refused" tabindex="-1">When the agent is refused <a class="header-anchor" href="#when-the-agent-is-refused" aria-label="Permalink to &quot;When the agent is refused&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What the refusal says</th><th>What to do</th></tr></thead><tbody><tr><td><code>type</code> marker outside the five</td><td><code>cadrage:markerInvalid</code></td><td>Pass <code>Découverte</code>, <code>Fonctionnalité</code>, <code>Amélioration</code>, <code>Anomalie</code> or <code>Test</code>.</td></tr><tr><td><code>status</code> outside the list</td><td><code>cadrage:statusInvalid</code></td><td>Pass <code>Planifié</code>, <code>En cours</code>, <code>En Attente</code>, <code>Résolu</code> or <code>Retiré</code>.</td></tr><tr><td><code>criticality</code> or <code>priority</code> outside 1 to 3</td><td><code>cadrage:levelOutOfRange</code></td><td>Pass an integer from 1 to 3, or omit the field to leave the entry unranked.</td></tr><tr><td>Anomaly filed although it was born in the current piece of work</td><td><code>cadrage:evolutionNeeDuChantier</code></td><td>Fix it within the work: <code>task_add</code> opens the task that carries it.</td></tr><tr><td>Unknown evolution identifier</td><td><code>cadrage:evolutionUnknown</code> (or <code>cadrage:evolutionNotFound</code> for <code>graduate</code>)</td><td>Read the register with <code>evolution_list</code> and use the right identifier.</td></tr><tr><td><code>form</code> other than <code>full</code> or <code>compact</code></td><td><code>cadrage:evolutionSearchFormInvalide</code></td><td>Pass <code>full</code> or <code>compact</code>.</td></tr><tr><td><code>evolution_edit</code> with no field</td><td><code>cadrage:evolutionEditEmpty</code></td><td>Pass at least <code>criticality</code>, <code>priority</code> or <code>detail</code>.</td></tr><tr><td>Resolving, retiring or marking ready an evolution already <code>Résolu</code> or <code>Retiré</code></td><td><code>cadrage:evolutionAlreadyTerminal</code></td><td>Nothing to lift: a terminal status can no longer be changed. Open a new entry if the subject comes back.</td></tr><tr><td>Requalifying anything other than Anomalie to Amélioration, or the reverse</td><td><code>cadrage:requalifyNotAllowed</code></td><td>Retire the entry, then open one with the right marker.</td></tr><tr><td>Retiring without a reason</td><td><code>cadrage:evolutionRetireReasonRequired</code></td><td>Pass <code>reason</code>.</td></tr><tr><td>Resolving without a reason</td><td><code>cadrage:evolutionResolveNoteRequired</code></td><td>Pass <code>note</code>.</td></tr><tr><td>Dependency that closes a cycle, or of an evolution on itself</td><td><code>cadrage:dependencyCycle</code></td><td>Choose another target.</td></tr><tr><td>Dependency on a non-existent evolution</td><td><code>cadrage:dependencyUnknown</code></td><td>Check the identifier with <code>evolution_list</code>.</td></tr><tr><td>Dependency target that is neither an evolution nor an epic</td><td><code>cadrage:dependencyUnknownShape</code></td><td>Pass the identifier of an evolution or an epic.</td></tr></tbody></table>',22))])}const _=i(c,[["render",h]]);export{y as __pageData,_ as default};
